import { Character, CharacterSkill, StatKey } from '../../api/character.dto';

// Invented sample character for stories and tests. The values are made up, not taken from any rulebook.

const stat = (temporary: number, potential: number, totalBonus: number) => ({
  temporary,
  potential,
  totalBonus,
  modifiers: {},
});

let skillSeq = 0;
const skill = (
  skillId: string,
  category: string,
  statistics: StatKey[],
  ranks: number,
  totalBonus: number,
  extra: Partial<CharacterSkill> = {}
): CharacterSkill => ({
  id: `skill-${++skillSeq}`,
  skillId,
  category,
  statistics,
  ranks,
  ranksDeveloped: 0,
  development: [],
  statBonus: Math.round(totalBonus / 3),
  racialBonus: 0,
  professionalBonus: extra.professional?.includes('professional') ? 5 : 0,
  developmentBonus: rankBonus(ranks),
  customBonus: 0,
  totalBonus,
  ...extra,
});

// Rank bonus of Core Law table 3-0b, as rmu-api-strategic computes it (spec 029)
const rankBonus = (ranks: number): number =>
  ranks <= 0
    ? -25
    : Math.min(ranks, 10) * 5 +
      Math.min(Math.max(ranks - 10, 0), 10) * 3 +
      Math.min(Math.max(ranks - 20, 0), 10) * 2 +
      Math.max(ranks - 30, 0);

